package com.greenbotz.greengate.ui.screens.auth

data class CountryInfo(
    val iso2: String,
    val name: String,
    val dialCode: String
) {
    // Emoji flag: two regional-indicator symbols. Each is above U+FFFF (two UTF-16 chars),
    // so it must be built from code points; Char would cut it down to an invalid character.
    val flag: String
        get() = buildString { iso2.uppercase().forEach { appendCodePoint(0x1F1E6 + (it - 'A')) } }
}

